CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, admin INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER REFERENCES users(id), expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY, payload TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS cart(id INTEGER PRIMARY KEY, owner TEXT NOT NULL REFERENCES sessions(token) ON DELETE CASCADE, product_id INTEGER NOT NULL REFERENCES products(id), size TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS favorites(owner TEXT NOT NULL REFERENCES sessions(token) ON DELETE CASCADE, product_id INTEGER NOT NULL REFERENCES products(id), PRIMARY KEY(owner,product_id));
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), address TEXT NOT NULL, total_cents INTEGER NOT NULL, created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'recebido', shipping_cents INTEGER NOT NULL DEFAULT 0, payment_method TEXT NOT NULL DEFAULT 'legado', payment_status TEXT NOT NULL DEFAULT 'nao_processado', payment_reference TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), product_id INTEGER NOT NULL REFERENCES products(id), name TEXT NOT NULL, size TEXT NOT NULL, price_cents INTEGER NOT NULL);

CREATE TABLE IF NOT EXISTS profiles(user_id INTEGER PRIMARY KEY REFERENCES users(id), payload TEXT NOT NULL);
